import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"16、【豫】 坤下震上","description":"周易集註 - 16、【豫】 坤下震上","frontmatter":{"title":"16、【豫】 坤下震上","description":"周易集註 - 16、【豫】 坤下震上"},"headers":[],"relativePath":"classics/jizhu/020.md","filePath":"classics/jizhu/020.md"}'),t={name:"classics/jizhu/020.md"};function h(l,a,s,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_16、【豫】-坤下震上" tabindex="-1">16、【豫】 坤下震上 <a class="header-anchor" href="#_16、【豫】-坤下震上" aria-label="Permalink to “16、【豫】 坤下震上”">​</a></h1><p>豫者和樂也，陽始潛閉於地中，及其動而出地，奮發其聲，通暢和豫，豫之象也。內順外動，豫之由也。《序卦》“有大而能謙必豫，故受之以豫”，所以次謙。</p><p>震長子主器，震驚百里，建侯之象。中爻坎陷，一陽統眾陰，行師之象。屯有震無坤，則言建侯，謙有坤無震，則言行師，此震坤合故兼言也。</p><p>《彖》曰：豫剛應而志行，順以動，豫。豫順以動，故天地如之，而況建侯行師乎。天地以順動，故日月不過，而四時不忒。聖人以順動，則刑罰清而民服，豫之時義大矣哉。</p><p>以卦體卦德釋卦名卦辭，而極言之。剛九四也，剛應者，一陽而眾陰從之也。志行者，陽之志得行也。剛應志行豫也，內順外動，所以成其豫也，故名豫。人事合乎天理則順，背乎天理則逆，順以動則一念一事皆天理矣。天地如之者，言天地亦不過如我之順動也。天地且不之違，而況於人之建侯行師乎。此其所以利也。建侯行師雖大事，較之天地則小矣。天地以順動者，順其自然之氣;聖人以順動者，順其當然之理。不過者，不差過也，如夏至晝六十刻夜四十刻，冬至晝四十刻夜六十刻之類是也。不忒者，不愆忒也，如夏則暑，冬則寒之類是也。刑罰不合乎理，惟乘一己喜怒之私，故民不服。若順動合乎天理之公，縱施刑罰，亦天刑也，故民服。時義者，豫中事理之時宜也，即順動也，此極言而贊之也。六十四卦時而已矣，事若淺而有深意，曰時義大矣哉，欲人思之也。非美事有時或用之，曰時用大矣哉，欲人則之也。大事大變曰時大矣哉，欲人謹之也。</p><h3 id="《象》曰-雷出地奮-豫。先王以作樂崇德-殷薦之上帝-以配祖考。" tabindex="-1">《象》曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。 <a class="header-anchor" href="#《象》曰-雷出地奮-豫。先王以作樂崇德-殷薦之上帝-以配祖考。" aria-label="Permalink to “《象》曰：雷出地奮，豫。先王以作樂崇德，殷薦之上帝，以配祖考。”">​</a></h3><p>奮者，奮發而成聲也。作，乃制禮作樂之作，作樂以崇德，故聞樂知德。殷，盛也，作樂乃朝廷邦國之常典，各有所主，其樂不同，惟萬物本乎天，故有郊，人本乎祖，故有廟，是其用樂之最大者，故曰殷薦。故冬至祀上帝於圜丘，而配之以祖，必以是樂薦之。季秋祀上帝於明堂，而配之以考，必以是樂薦之。卦中爻坎為樂律，樂之象，五陰而崇一陽德，崇德之象。帝出於震，上帝之象，中爻艮為門闕，坎為隱伏，宗廟祖宗之象。</p><p>初六，鳴豫，兇。</p><p>鳴，詳見鳴謙。謙豫二卦同體，文王綜為一卦，故《雜卦》曰“謙輕而豫怠也”。謙之上六，即豫之初六，故二爻皆言鳴。震性動又決躁，所以浚恆兇，飛鳥兇。</p><p>初六與九四為正應，九四由豫，初據其應與之常，欲相從乎四而和之，故有鳴豫之象。然初位卑，四近君，乃權臣也。正其志大行之時，上下既懸絕，且初又不中正，應與之情乖矣，豈能與四彼此唱和?其豫不能唱和，初之志窮矣，兇之道也，故佔者兇。</p><h3 id="《象》曰-初六鳴豫-志窮兇也。" tabindex="-1">《象》曰：初六鳴豫，志窮兇也。 <a class="header-anchor" href="#《象》曰-初六鳴豫-志窮兇也。" aria-label="Permalink to “《象》曰：初六鳴豫，志窮兇也。”">​</a></h3><p>惟志窮所以兇。中孚鶴鳴子和，曰中心願也，六二鳴謙，曰中心得也，此心志相孚者也。上六鳴謙，曰志未得也，初六鳴豫，曰志窮兇也，此心志不相孚者也。相孚者皆曰心，不相孚者皆曰志，此所以為聖人之言。</p><p>六二，介於石，不終日，貞吉。</p><p>凡物分為兩間者曰介，二變剛，分坤為兩間，介之象也。介於石者，言操守之堅，如石不可移易，中爻艮石之象也。不終日者，不溺於豫，見幾而作，不待其日之晚也。二變，中爻離，且居下卦之上，不終日之象也。八卦正位，坤在二，故貞吉。</p><p>豫易以溺人，諸爻皆溺於豫，獨六二中正自守，安靜堅確，故有此象，正而且吉之道也，故其佔如此。</p><h3 id="《象》曰-不終日-貞吉-以中正也。" tabindex="-1">《象》曰：不終日，貞吉，以中正也。 <a class="header-anchor" href="#《象》曰-不終日-貞吉-以中正也。" aria-label="Permalink to “《象》曰：不終日，貞吉，以中正也。”">​</a></h3><p>惟中正，故不終日貞吉。</p><p>六三，盱豫，悔遲有悔。</p><p>盱者，張目也。中爻錯離，目之象也。盱目以為豫者，九四當權，三與親比，幸其權勢之足憑，而自縱其所欲也。盱與介相反，遲與不終日相反。二中正，三不中正故也。</p><p>四為豫之主，六三陰柔，不中不正，而近於四，上視於四，而溺於豫，宜有悔者也，故有此象。而其佔為事當速悔，若悔之遲，則過而不改，是謂過矣。此聖人為佔者開遷善之門，而勉之以速改也。</p><h3 id="《象》曰-盱豫有悔-位不當也。" tabindex="-1">《象》曰：盱豫有悔，位不當也。 <a class="header-anchor" href="#《象》曰-盱豫有悔-位不當也。" aria-label="Permalink to “《象》曰：盱豫有悔，位不當也。”">​</a></h3><p>六三不中不正，故位不當。</p><p>九四，由豫，大有得，勿疑，朋盍簪。</p><p>由豫者，言人心之和豫，由四而致也。本卦一陽為動之主，動而眾陰悅從，故曰由豫。大有得者，言得大行其志，以致天下之豫也。四多疑懼，故曰疑。又中爻坎，亦為狐疑。勿疑者，中爻艮止，止而不疑之象也。因九四才剛明，故教之以勿疑也。盍者合也，簪者首笄也，婦人冠上之飾，所以緫聚其髪者也。下坤，婦人之象也，一陽橫於三陰之首，簪之象也。勿疑朋盍簪者，勿疑朋合於我者，皆簪冠之婦人也。</p><p>九四一陽居五陰之中，人所由以為豫，故有由豫之象。佔者遇此，故為大有得。然人既樂從，正當得志之時，必展其大行之志，俾人人皆享其和平豫大之福，勿疑由豫於我者，無同德之陽明而所以朋合於上下內外者，皆陰柔之群小可也。故又教佔者，必不可疑如此。</p><h3 id="《象》曰-由豫-大有得-志大行也。" tabindex="-1">《象》曰：由豫，大有得，志大行也。 <a class="header-anchor" href="#《象》曰-由豫-大有得-志大行也。" aria-label="Permalink to “《象》曰：由豫，大有得，志大行也。”">​</a></h3><p>剛應而無他爻以分其權，故曰志大行。</p><p>六五，貞疾，恆不死。</p><p>中爻為坎，坎為心病，疾之象也。曰貞疾者，言非假疾，疾之在外而可以藥石者也。九四由豫，人心通歸於四，危之極矣。下卦坤為腹，凡四居卦之中為心，即鹹卦憧憧往來之爻也。此正腹中心疾，故謂之貞疾。恆者常也，言貞疾而常不死也。周室衰微，此爻近之。</p><p>六五當豫之時，柔不能立，而又乘九四之剛，權之所主，眾之所歸，皆在於四。衰弱極矣，故有貞疾之象。然以其得中，故又有恆不死之象。即象而佔可知矣。</p><h3 id="《象》曰-六五貞疾-乘剛也。恆不死-中未亡也。" tabindex="-1">《象》曰：六五貞疾，乘剛也。恆不死，中未亡也。 <a class="header-anchor" href="#《象》曰-六五貞疾-乘剛也。恆不死-中未亡也。" aria-label="Permalink to “《象》曰：六五貞疾，乘剛也。恆不死，中未亡也。”">​</a></h3><p>雖乘四，為剛所逼，然柔而得中，猶存虛位不死。</p><p>上六，冥豫，成有渝，無咎。</p><p>冥者，幽也，暗也。上六以陰柔居豫極，為昏冥於豫之象。成者，五陰同豫，至上六已成矣，然以動體變剛成離，則前之冥冥者今反昭昭矣，故又為其事雖成，然樂極哀生，不免有悔心之萌，而能改變之象。佔者如是，則能補過矣，故無咎。</p><h3 id="《象》曰-冥豫在上-何可長也。" tabindex="-1">《象》曰：冥豫在上，何可長也。 <a class="header-anchor" href="#《象》曰-冥豫在上-何可長也。" aria-label="Permalink to “《象》曰：冥豫在上，何可長也。”">​</a></h3><p>豫已極矣，宜當速改，何可長溺於豫而不返也。</p>',36)])])}const m=e(t,[["render",h]]);export{_ as __pageData,m as default};
